  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "प्रत्येक कर्मचाऱ्यासाठी. प्रत्येक वेब पंचसाठी मंजूर Face ID शी थेट चेहरा जुळणे आवश्यक आहे; तो तयार होईपर्यंत, तुम्ही खालील पर्याय परवानगी दिल्याशिवाय वेब क्लॉक-इन/आउट रोखले जाते.",
