  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "कर्मचारी किती दिवस मागे घरून कामाची विनंती करू शकतो. परवानगी नाही (शिफारस केलेले): फक्त आजची किंवा पुढील तारीख, कारण मागील दिवसाची मंजूर विनंती त्या दिवसाची स्थिती नंतर बदलते आणि घराच्या ठिकाणाची तपासणी पूर्ण होऊ शकत नाही.",
