  "I have verified these values and I am authorised to apply this separation.": "मी ही मूल्ये तपासली आहेत आणि ही सेवासमाप्ती लागू करण्याचा मला अधिकार आहे.",
  "Pending approval — a real multi-stage approval chain runs on this request.": "मंजुरी प्रलंबित — या विनंतीवर खरी बहु-टप्पी मंजुरी साखळी चालते.",
  "Pending approval — nothing changes until every approver on the route has approved.": "मंजुरी प्रलंबित — मार्गावरील प्रत्येक मंजुरी देणाऱ्याने मंजुरी देईपर्यंत काहीही बदलत नाही.",
  "Raised by": "नोंदवणारा",
  "Recording a separation ends the current record and starts the exit process. It cannot be reversed — a returning employee needs a fresh Hire action.": "सेवासमाप्ती नोंदवल्याने सध्याची नोंद संपते आणि निर्गमन प्रक्रिया सुरू होते. हे पूर्ववत करता येत नाही — परत येणाऱ्या कर्मचाऱ्यासाठी नवीन नियुक्ती कृती आवश्यक आहे.",
  "Reversibility": "पूर्ववत करण्याची क्षमता",
  "Status on apply": "लागू केल्यावर स्थिती",
  "This cannot be undone": "हे पूर्ववत करता येणार नाही",
  "unchanged": "बदललेले नाही",
  "HR Business Partner → Payroll Admin.": "एचआर बिझनेस पार्टनर → पेरोल ॲडमिन.",
  "HR, then Branch Admin (this employee is a manager, per the real separation approval chain).": "एचआर, नंतर शाखा ॲडमिन (हा कर्मचारी व्यवस्थापक आहे, खऱ्या सेवासमाप्ती मंजुरी साखळीनुसार).",
  "Not reversible. Undoing a separation requires a fresh Hire action and a new employee record — the original number is not reissued.": "पूर्ववत करता येत नाही. सेवासमाप्ती रद्द करण्यासाठी नवीन नियुक्ती कृती आणि नवीन कर्मचारी नोंद आवश्यक आहे — मूळ क्रमांक पुन्हा दिला जात नाही.",
  "Reporting manager (raises) → HR Business Partner, then Payroll Admin if a new CTC is included.": "रिपोर्टिंग व्यवस्थापक (नोंदवतो) → एचआर बिझनेस पार्टनर, नवीन CTC समाविष्ट असल्यास नंतर पेरोल ॲडमिन.",
  "Reporting manager (raises) → HR Business Partner.": "रिपोर्टिंग व्यवस्थापक (नोंदवतो) → एचआर बिझनेस पार्टनर.",
  "Reporting manager, then HR (the real separation approval chain for this employee).": "रिपोर्टिंग व्यवस्थापक, नंतर एचआर (या कर्मचाऱ्यासाठी खरी सेवासमाप्ती मंजुरी साखळी).",
  "Requires employees.confirm — HR/Admin applies this directly, with the effective date and reason recorded in the audit trail.": "employees.confirm आवश्यक — एचआर/ॲडमिन हे थेट लागू करतो, प्रभावी तारीख आणि कारण ऑडिट ट्रेलमध्ये नोंदवले जाते.",
  "Requires employees.edit — applied directly by whoever has that permission (typically the reporting manager or HR); no queued approval step exists for this action yet.": "employees.edit आवश्यक — ती परवानगी असलेली व्यक्ती (सहसा रिपोर्टिंग व्यवस्थापक किंवा एचआर) हे थेट लागू करते; या कृतीसाठी अद्याप रांगेतील मंजुरी टप्पा नाही.",
  "Requires employees.edit — currently held by {name} or HR; no queued approval step exists for this action yet.": "employees.edit आवश्यक — सध्या {name} किंवा एचआरकडे आहे; या कृतीसाठी अद्याप रांगेतील मंजुरी टप्पा नाही.",
  "Requires employees.edit; no queued approval step exists for this action yet.": "employees.edit आवश्यक; या कृतीसाठी अद्याप रांगेतील मंजुरी टप्पा नाही.",
  "Requires payroll.edit — typically an HR Business Partner or Payroll Admin; no queued approval step exists for this action yet.": "payroll.edit आवश्यक — सहसा एचआर बिझनेस पार्टनर किंवा पेरोल ॲडमिन; या कृतीसाठी अद्याप रांगेतील मंजुरी टप्पा नाही.",
  "Reversible going forward, but any payroll run already processed on this record must be corrected through arrears.": "पुढे पूर्ववत करता येते, पण या नोंदीवर आधीच प्रोसेस झालेला कोणताही पेरोल थकबाकीद्वारे दुरुस्त करावा लागतो.",
  "Reversible. A correction action delimits this record and restores the previous position; the history keeps both.": "पूर्ववत करता येते. दुरुस्ती कृती ही नोंद संपवते आणि मागील पद पुन्हा लागू करते; इतिहासात दोन्ही राहतात.",
  "Reversible. Record a further org assignment to move the employee back.": "पूर्ववत करता येते. कर्मचाऱ्याला परत हलवण्यासाठी आणखी एक संस्था नेमणूक नोंदवा.",
  "This is a one-way transition from probation to confirmed/active. Verify the employee and effective date before applying.": "हे परीविक्षेतून निश्चित/सक्रिय स्थितीकडे जाणारे एकदिशा संक्रमण आहे. लागू करण्यापूर्वी कर्मचारी आणि प्रभावी तारीख तपासा.",
