  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "कर्मचाऱ्याला या कॅमेऱ्यासमोर बसवा, मग सुरू करा — जतन करण्यापूर्वी जलद लाइव्हनेस तपासणी ती व्यक्ती खरोखर तीच असल्याची खात्री करते.",
