  "Register Face ID — {name}": "Face ID नोंदवा — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID नोंदवण्यासाठी कॅमेरा वापरण्याची परवानगी लागते. तुमच्या ब्राउझरच्या सेटिंग्जमध्ये या साइटसाठी परवानगी द्या, मग पुन्हा प्रयत्न करा.",
  "Registering face ID…": "Face ID नोंदवत आहे…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "नोंदणीसाठी नैसर्गिक डोळ्यांची उघडझाप आणि डोके थोडे वळवणे दोन्ही लागतात, आणि दोन्ही वेळेत दिसले नाहीत. चेहऱ्यावर पुरेसा प्रकाश आणि चेहरा मध्यभागी असल्याची खात्री करा, मग पुन्हा प्रयत्न करा.",
  "Requesting camera access": "कॅमेरा परवानगी मागत आहे",
