  "Try Again": "पुन्हा प्रयत्न करा",
  "Update {name}'s face": "{name} यांचा चेहरा अद्ययावत करा",
  "Update Face ID — {name}": "Face ID अद्ययावत करा — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "आम्हाला खात्रीशीर स्पष्ट कॅप्चर मिळाले नाही — हेच त्यांचा कायमचा Face ID संदर्भ बनते, त्यामुळे ते नीट असणे महत्त्वाचे आहे. अधिक चांगला प्रकाश वापरा आणि त्यांना स्थिर राहायला सांगा.",
