  "Scan & fill": "स्कॅन करा आणि भरा",
  "The draft and everything entered so far will be deleted, and its reserved employee number is released. This cannot be undone. To keep it, use Save & exit instead.": "मसुदा आणि आतापर्यंत टाकलेले सर्व काही हटवले जाईल, आणि त्यासाठी राखीव कर्मचारी क्रमांक मोकळा होईल. हे पूर्ववत करता येणार नाही. ठेवण्यासाठी त्याऐवजी \"जतन करा आणि बाहेर पडा\" वापरा.",
  "The new hire": "नवीन कर्मचारी",
  "The server did not keep: {fields}. Nothing was hired. Open that step, re-enter it, wait for \"Saved\", and press Hire again.": "सर्व्हरने हे जतन केले नाही: {fields}. कोणतीही नेमणूक झाली नाही. ती पायरी उघडा, पुन्हा टाका, \"जतन झाले\" दिसेपर्यंत थांबा आणि पुन्हा नेमा दाबा.",
  "Type the first and last name first. Suggest builds the display name from them.": "आधी नाव आणि आडनाव टाका. \"सुचवा\" त्यावरून दाखवायचे नाव तयार करते.",
