  "Permanently delete \"{name}\"? This can't be undone, and only works if none of its positions have ever been held by anyone — if any have, this will be rejected; deactivate the unit instead.": "\"{name}\" कायमचे हटवायचे का? हे पूर्ववत करता येणार नाही, आणि त्यातील कोणत्याही पदावर कधीही कोणी नसेल तरच हे चालते — असल्यास हे नाकारले जाईल; त्याऐवजी घटक निष्क्रिय करा.",
