  "Team manager": "टीम व्यवस्थापक",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "या परवानग्या या पदाच्या आहेत. सध्याच्या धारकाला त्या मिळतात; भविष्यातील धारकालाही तोच प्रवेश मिळतो. परवानग्या व्यवस्थापक आणि त्यांच्या रिपोर्टमध्ये आपोआप हस्तांतरित होत नाहीत. प्रत्येक पदाला खाली स्वतःचा प्रवेश द्या.",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "टीम व्यवस्थापक सुरू केल्याने खालील नेहमीच्या व्यवस्थापक परवानग्या (कर्मचारी पाहणे, रजा मंजूर करणे, उपस्थिती पाहणे) देखील निवडल्या गेल्या, जेणेकरून या पदाकडे 0 परवानग्या राहू नयेत. जतन करण्यापूर्वी नको असलेल्या परवानग्यांची निवड काढा.",
