  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "एचआर/ॲडमिनने L1 टप्पा थेट पूर्ण करण्याची प्रतीक्षा — या चक्रासाठी कोणतेही व्यवस्थापक नेमलेले नाहीत.",
  "Waiting for other managers to approve. Refresh to check latest status.": "इतर व्यवस्थापकांच्या मंजुरीची प्रतीक्षा. नवीनतम स्थिती पाहण्यासाठी रिफ्रेश करा.",
