  "Download NEFT CSV": "NEFT CSV डाउनलोड करा",
  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "कर्मचाऱ्यांनी त्यांच्या पगारपावत्या मान्य केल्या आहेत. बँक तपशील लॉक करण्यासाठी आणि NEFT CSV तयार करण्यासाठी पगार हस्तांतरणाची पुष्टी करा.",
