  "Locking Transfer…": "हस्तांतरण लॉक होत आहे…",
  "Mark All Paid": "सर्व दिले म्हणून नोंदवा",
  "Mark Payroll as Paid": "पेरोल दिले म्हणून नोंदवा",
  "Mark payroll as paid?": "पेरोल दिले म्हणून नोंदवायचे का?",
  "Marking Paid…": "दिले म्हणून नोंदवत आहे…",
  "Net Salary": "निव्वळ पगार",
  "Paid": "दिले",
  "Preparing CSV…": "CSV तयार होत आहे…",
  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} कर्मचाऱ्यांसाठी पगार हस्तांतरण लॉक केले. पेरोल दिले म्हणून नोंदवण्यापूर्वी NEFT CSV डाउनलोड करून तुमच्या बँकेकडे सादर करा.",
  "Salary transfer readiness is unavailable.": "पगार हस्तांतरणाची तयारी उपलब्ध नाही.",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "यामुळे सर्व {count} कर्मचाऱ्यांचे सध्याचे बँक तपशील आणि निव्वळ पगार एका हस्तांतरण बॅचमध्ये लॉक होतात. पुष्टीनंतर NEFT CSV डाउनलोड करा आणि पेरोल दिले म्हणून नोंदवण्यापूर्वी ती तुमच्या बँकेमार्फत सादर करा.",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "यामुळे सर्व {count} पगारपावत्या (एकूण {amount}) दिल्या म्हणून नोंदवल्या जातात आणि हा पेरोल रन बंद होतो. यातून पैसे हस्तांतरित होत नाहीत — हस्तांतरण आधीच झाले आहे याची नोंद होते. हे पूर्ववत करता येत नाही.",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "यामुळे सर्व {count} पगारपावत्या (एकूण {amount}) दिल्या म्हणून नोंदवल्या जातात आणि हा पेरोल रन बंद होतो. यातून पैसे हस्तांतरित होत नाहीत — हस्तांतरण आधीच झाले आहे याची नोंद होते. हे पूर्ववत करता येत नाही.",
