  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "प्रमाणशीर पगार, रजा रोखीकरण आणि नोटीस कालावधीची कमतरता आपोआप मोजली जाते (CTC ÷ 30, अर्जित रजा शिल्लक) — हा तपासण्यासाठी प्राथमिक अंदाज आहे, अंतिम आकडा नाही. ग्रॅच्युइटी, बोनस, परतफेड, आगाऊ रक्कम आणि TDS नेहमी हाताने टाकावे लागतात.",
