  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "यामुळे पूर्ण आणि अंतिम सेटलमेंट {amount} च्या देय निव्वळ रकमेवर लॉक होते. एकदा अंतिम केल्यावर या सेटलमेंटमधील कोणताही रकाना — ग्रॅच्युइटी, बोनस, परतफेड, आगाऊ रक्कम, TDS किंवा समायोजने — पुन्हा संपादित करता येणार नाही. हे पूर्ववत करता येत नाही.",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "यामुळे पूर्ण आणि अंतिम सेटलमेंट कर्मचाऱ्याकडून वसूल करायच्या {amount} निव्वळ रकमेवर लॉक होते. एकदा अंतिम केल्यावर या सेटलमेंटमधील कोणताही रकाना — ग्रॅच्युइटी, बोनस, परतफेड, आगाऊ रक्कम, TDS किंवा समायोजने — पुन्हा संपादित करता येणार नाही. हे पूर्ववत करता येत नाही.",
