  "This CIN's listing prefix (L) marks it as a listed company, which isn't possible for this entity type.": "या CIN मधील सूचिबद्धता उपसर्ग (L) ही सूचिबद्ध कंपनी दर्शवतो, जे या संस्था प्रकारासाठी शक्य नाही.",
