  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure you're well-lit and centered, then try again.": "नोंदणीसाठी सहज डोळे मिचकावणे आणि थोडे डोके वळवणे दोन्ही आवश्यक आहे, आणि वेळेत दोन्ही दिसले नाही. पुरेसा प्रकाश असल्याची आणि चेहरा मध्यभागी असल्याची खात्री करा, मग पुन्हा प्रयत्न करा.",
  "Registration submitted!": "नोंदणी सादर झाली!",
  "Sending your registration for approval…": "तुमची नोंदणी मंजुरीसाठी पाठवत आहे…",
  "Submitting": "सादर होत आहे",
  "Update your face ID": "तुमचा Face ID अद्ययावत करा",
  "We couldn't get a reliably clear capture — this becomes your permanent face ID reference, so it's worth getting right. Try better lighting and hold steady.": "आम्हाला स्पष्ट प्रतिमा मिळू शकली नाही — हीच तुमचा कायमस्वरूपी Face ID संदर्भ बनते, त्यामुळे ती नीट येणे महत्त्वाचे आहे. चांगला प्रकाश ठेवा आणि स्थिर राहा.",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "आम्ही कॅमेरा प्रवेश मागू, तुम्हीच आहात याची खात्री करण्यासाठी झटपट लाइव्हनेस तपासणी (डोळे मिचकावणे आणि थोडे डोके वळवणे) करू, मग तुमचा Face ID एचआर मंजुरीसाठी पाठवू. कोणताही फोटो किंवा व्हिडिओ पाठवला जात नाही — फक्त संख्यात्मक चेहरा स्वाक्षरी पाठवली जाते.",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your updated face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "आम्ही कॅमेरा प्रवेश मागू, तुम्हीच आहात याची खात्री करण्यासाठी झटपट लाइव्हनेस तपासणी (डोळे मिचकावणे आणि थोडे डोके वळवणे) करू, मग तुमचा अद्ययावत Face ID एचआर मंजुरीसाठी पाठवू. कोणताही फोटो किंवा व्हिडिओ पाठवला जात नाही — फक्त संख्यात्मक चेहरा स्वाक्षरी पाठवली जाते.",
  "Your face registration request has been sent to HR for approval. You'll be notified once it's reviewed.": "तुमची चेहरा नोंदणी विनंती मंजुरीसाठी एचआरकडे पाठवली आहे. आढावा झाल्यावर तुम्हाला कळवले जाईल.",
  "Low light detected — your screen is now acting as a light. Raising your screen brightness helps.": "कमी प्रकाश आढळला — तुमची स्क्रीन आता प्रकाशासारखी काम करत आहे. स्क्रीनची ब्राइटनेस वाढवल्यास मदत होईल.",
  "Please allow camera access in the browser prompt to punch in or out.": "पंच इन किंवा आउट करण्यासाठी ब्राउझरच्या सूचनेत कॅमेरा प्रवेश द्या.",
  "Preparing face verification": "चेहरा पडताळणी तयार होत आहे",
  "Verify Your Identity": "तुमची ओळख पडताळा",
  "We couldn't get a reliably clear capture to verify against your registered face. Try better lighting and hold steady.": "तुमच्या नोंदणीकृत चेहऱ्याशी पडताळण्यासाठी स्पष्ट प्रतिमा मिळू शकली नाही. चांगला प्रकाश ठेवा आणि स्थिर राहा.",
  "We didn't detect a slight head turn in time. Make sure you're well-lit and centered, then try again.": "वेळेत थोडे डोके वळवलेले आढळले नाही. पुरेसा प्रकाश असल्याची आणि चेहरा मध्यभागी असल्याची खात्री करा, मग पुन्हा प्रयत्न करा.",
  "Your account requires face verification to punch in or out. Allow camera access for this site in your browser's settings, then try again.": "पंच इन किंवा आउट करण्यासाठी तुमच्या खात्याला चेहरा पडताळणी आवश्यक आहे. तुमच्या ब्राउझरच्या सेटिंग्जमध्ये या साइटसाठी कॅमेरा प्रवेश द्या, मग पुन्हा प्रयत्न करा.",
