  "Who sees what": "कोणाला काय दिसते",
  "You cannot approve your own leave or expense requests.": "तुम्ही तुमच्या स्वतःच्या रजा किंवा खर्च विनंत्या मंजूर करू शकत नाही.",
  "You stay signed in for up to 7 days. The short-lived part of your sign-in lasts 15 minutes and is renewed automatically while you are signed in.": "तुम्ही जास्तीत जास्त 7 दिवस साइन इन राहता. तुमच्या साइन इनचा अल्पकालीन भाग 15 मिनिटे टिकतो आणि तुम्ही साइन इन असताना तो आपोआप नूतनीकृत होतो.",
