  "unlimited attempts": "अमर्याद प्रयत्न",
  "The connection was lost and the import status could not be checked. Refresh the employee list to see which employees were created before uploading again; rows whose email already exists are skipped, so a second upload will not create duplicates.": "कनेक्शन तुटले आणि इम्पोर्टची स्थिती तपासता आली नाही. पुन्हा अपलोड करण्यापूर्वी कोणते कर्मचारी तयार झाले ते पाहण्यासाठी कर्मचारी यादी रिफ्रेश करा; ज्या ओळींचा ईमेल आधीच अस्तित्वात आहे त्या वगळल्या जातात, त्यामुळे दुसऱ्यांदा अपलोड केल्याने डुप्लिकेट तयार होणार नाहीत.",
  "The import finished on the server: {created} created, {skipped} skipped, {failed} failed out of {total} rows. Refresh the employee list to see them. Do not upload the same file again.": "सर्व्हरवर इम्पोर्ट पूर्ण झाले: {total} ओळींपैकी {created} तयार, {skipped} वगळल्या, {failed} अयशस्वी. ते पाहण्यासाठी कर्मचारी यादी रिफ्रेश करा. तीच फाइल पुन्हा अपलोड करू नका.",
  "The import is still running on the server ({created} employees created so far). Wait a minute and refresh the employee list before doing anything else.": "सर्व्हरवर इम्पोर्ट अजून सुरू आहे (आतापर्यंत {created} कर्मचारी तयार झाले). दुसरे काहीही करण्यापूर्वी एक मिनिट थांबा आणि कर्मचारी यादी रिफ्रेश करा.",
  "The import never reached the server, so no employees were created. It is safe to upload the file again.": "इम्पोर्ट सर्व्हरपर्यंत पोहोचलेच नाही, त्यामुळे कोणतेही कर्मचारी तयार झाले नाहीत. फाइल पुन्हा अपलोड करणे सुरक्षित आहे.",
  "The import was interrupted before it finished. About {created} of {total} employees were created. It is safe to upload the same file again: rows whose email already exists are skipped.": "इम्पोर्ट पूर्ण होण्यापूर्वी खंडित झाले. {total} पैकी सुमारे {created} कर्मचारी तयार झाले. तीच फाइल पुन्हा अपलोड करणे सुरक्षित आहे: ज्या ओळींचा ईमेल आधीच अस्तित्वात आहे त्या वगळल्या जातात.",
  "File is too large ({size}). Maximum allowed size is {max}.": "फाइल खूप मोठी आहे ({size}). परवानगी असलेला कमाल आकार {max} आहे.",
  "Unsupported file type. Please choose a {types} file.": "असमर्थित फाइल प्रकार. कृपया {types} फाइल निवडा.",
  "{base} Sending is switched off by an administrator, so they are waiting.": "{base} ॲडमिनने पाठवणे बंद केले आहे, त्यामुळे ते प्रतीक्षेत आहेत.",
  "{base} The employees exist; retry the failed emails below.": "{base} कर्मचारी अस्तित्वात आहेत; अयशस्वी ईमेल खाली पुन्हा पाठवा.",
  "{count} not needed": "{count} गरज नाही",
  "{count} sent": "{count} पाठवले",
  "{created} {count} activation email could not be sent: the employees exist, use Resend Invite for them.": "{created} {count} सक्रियता ईमेल पाठवता आला नाही: कर्मचारी अस्तित्वात आहेत, त्यांच्यासाठी \"आमंत्रण पुन्हा पाठवा\" वापरा.",
  "{created} {count} activation emails could not be sent: the employees exist, use Resend Invite for them.": "{created} {count} सक्रियता ईमेल पाठवता आले नाहीत: कर्मचारी अस्तित्वात आहेत, त्यांच्यासाठी \"आमंत्रण पुन्हा पाठवा\" वापरा.",
