  "Creating employees: {processed} of {total} rows processed, {created} created, {failed} failed.": "कर्मचारी तयार करत आहे: {total} पैकी {processed} ओळी प्रोसेस झाल्या, {created} तयार, {failed} अयशस्वी.",
  "Creating employees: {processed} of {total} rows processed, {created} created.": "कर्मचारी तयार करत आहे: {total} पैकी {processed} ओळी प्रोसेस झाल्या, {created} तयार.",
  "Import cancelled. {people} had already been created and stay in the system.": "इम्पोर्ट रद्द केले. {people} आधीच तयार झाले होते आणि ते सिस्टममध्ये राहतील.",
